INSERT INTO `wp_options` VALUES (179842,'_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"Akismet: Akismet turns 21. Spam isn’t invited.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=285509\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://akismet.com/blog/akismet-turns-21-spam-isnt-invited/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5062:\"<p class=\"wp-block-paragraph\">On October 25, Akismet turns 21. We&#8217;re celebrating with a few new guests: an official Drupal module, a PHP SDK, and another year of improvements to our WordPress plugin. Spam still isn&#8217;t on the list.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Akismet <a href=\"https://ma.tt/2005/10/akismet-stops-spam/\">launched in October 2005</a> to help people spend less time dealing with comment spam and more time enjoying their blogs. The web has changed a lot since then. People build communities, collect inquiries, accept donations, and create applications on all kinds of platforms. Each of those places gives people a way to contribute. It also gives spammers somewhere to try their luck.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Since then, Akismet has blocked over 570 billion pieces of spam. Every one is something a site owner didn&#8217;t have to spend time sorting through. Our birthday wish is to keep making more room for the real people.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"welcome-drupal\">Welcome, Drupal</h3>\n\n\n\n<p class=\"wp-block-paragraph\">This year, we released the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-drupal-module/\">official Akismet Drupal module</a>, built by the team behind Akismet. It brings our spam protection to Drupal comments, contact forms, webforms, and user registrations, with tools for moderators to review submissions and send corrections back to Akismet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;ve continued building on that welcome. The latest release <a href=\"https://akismet.com/blog/akismet-now-supports-drupal-12/\">supports Drupal 12</a> and passes richer bot-detection signals into spam scoring. On Drupal 12, comments and registrations are supported now; contact forms, webforms, and the Key module will follow as those modules become ready for Drupal 12.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For people using the older community module, we also built an <a href=\"https://akismet.com/blog/upgrade-to-the-official-akismet-drupal-module/\">upgrade path to the official module</a> that carries their API key and protection settings across. The migration guide explains the requirements and which settings need attention.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"welcome-php-developers\">Welcome, PHP developers</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Akismet&#8217;s API has long made it possible to protect sites beyond WordPress. This year&#8217;s <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">official PHP SDK</a> gives developers a first-party client for bringing that protection into their own PHP applications, including projects built with Laravel or Symfony.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The SDK handles the Akismet API integration so developers can focus on their application. It supports checking submissions, reporting spam and legitimate content, and retrieving usage and account information. The official Drupal module uses it too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re building a place where people can post, sign up, or send a message, there&#8217;s a new tool to help you keep the spam out.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"a-familiar-guest-with-a-few-improvements\">A familiar guest, with a few improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress has been with us from the beginning. This year, we kept improving that experience: clearer setup and error messages, accessibility improvements, better detection of automated submissions, and compatibility fixes. You can find the details in the <a href=\"https://wordpress.org/plugins/akismet/#developers\">WordPress plugin release log</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://akismet.com/blog/akismet-v5-7-ready-for-abilities-and-connectors/\">Version 5.7 also added support for Abilities and Connectors</a>, helping Akismet fit into WordPress&#8217;s evolving tools for integrating external services.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"more-room-for-real-people\">More room for real people</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A comment worth replying to. A message from a future customer. A donation to a cause someone cares about. Those are the things we want coming through.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thank you to everyone who uses Akismet, builds an integration, reports a problem, or helps us improve. You&#8217;ve been part of these 21 years, and you&#8217;re very much invited to the celebration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whether your site runs on <a href=\"https://wordpress.org/plugins/akismet/\">WordPress</a>, <a href=\"https://akismet.com/blog/introducing-the-official-akismet-drupal-module/\">Drupal</a>, or something you&#8217;re building yourself with the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">PHP SDK</a>, there&#8217;s room at the table.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Just no room for spam.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.drupal.org/project/akismet_antispam\">Try out the Drupal module today!</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 26 Oct 2026 15:16:26 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Peter Westwood\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"Open Channels FM: AI in Cybersecurity: Balancing Speed and Human Oversight\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564606\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"https://openchannels.fm/ai-in-cybersecurity-balancing-speed-and-human-oversight/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:249:\"As AI revolutionizes cybersecurity, organizations struggle with rapid vulnerability detection versus slow human remediation. Balancing efficiency and accountability is crucial, as maintaining human oversight prevents potentially catastrophic errors.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 26 Oct 2026 11:35:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:110:\"Gutenberg Times: A critical PHP fix, WordPress 7.2 Beta 1, Notes in the margin, and more—Weekend Edition 378\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=47314\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"https://gutenbergtimes.com/a-critical-php-fix-wordpress-7-2-beta-1-notes-in-the-margin-and-more-weekend-edition-378/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:31285:\"<p class=\"wp-block-paragraph\">Howdy,</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before anything else: check which version of PHP your sites run. On October 21, the PHP project <a href=\"https://wordpress.org/news/2026/10/critical-php-security-release/\"><strong>released fixes for two critical vulnerabilities</strong></a>, and they affect any server running a PHP application, not only WordPress. You&#8217;ll find your version under <strong>Tools → Site Health → Info → Server</strong> in your WordPress admin. If you manage your own server and are still on a version older than 8.2, I highly recommend updating. While many hosts have patched older PHP versions that are end of life, it’s best to stay on versions that PHP officially supports.</p>\n\n\n\n<p class=\"wp-block-paragraph\">On a happier note, I&#8217;m back. I was sick for a stretch earlier this month, which is why there was no edition on October 10. Rather than try to cram four weeks into one post, this edition sticks to the last two. Much of what happened in the gap is covered in my October roundup for developers, linked below.</p>\n\n\n\n<p class=\"wp-block-paragraph\">With that, let&#8217;s get down to the latest news.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Your friendly neighborhood developer advocate, <img alt=\"🎃\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f383.png\" style=\"height: 1em;\" /><br /><em>Justin Tadlock</em></p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<div class=\"wp-block-group has-accent-5-background-color has-background has-global-padding is-layout-constrained wp-container-core-group-is-layout-b14348ac wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ul><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-word-press-release-information\">Developing Gutenberg and WordPress</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#what-s-new-in-playground\">What&#039;s new in Playground?</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#ai-in-wordpress\">AI in WordPress</a></li></ul></nav></div>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The final major release of the year has entered testing. <strong>David Baumwald</strong> announced that <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\"><strong>WordPress 7.2 Beta 1 is ready for download and testing</strong></a>, with the final release set for December 8. Notes move into a margin beside the canvas and pick up emoji reactions. Text shadows and form element styling arrive in the design tools, a new Secrets API gives plugins a standard place to store API keys, and client-side media processing extends to the Media Library. There&#8217;s even an <strong>On This Day</strong> dashboard widget. Not everything made it, though: The Repository reports that <a href=\"https://www.therepository.email/wordpress-7-2-beta-1-out-now-with-secrets-api-and-notes-upgrades-punts-suggestion-mode-to-7-3\"><strong>Notes suggestion mode was punted to 7.3</strong></a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The quickest way to try it is the 7.2 Beta 1 <a href=\"https://playground.wordpress.net/?php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\">Playground instance</a>, or <code>wp core update --version=7.2-beta1</code> on a test site. Not on production.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Not sure where to start? <strong>Noruzzaman&#8217;s</strong> <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\"><strong>Help Test WordPress 7.2</strong></a> breaks the release down by area: security, collaboration, admin, blocks and APIs, design, media. It also walks through the different ways to run a beta, from Playground to a staging site on your host, and points you to where feedback goes. The Beta 1 post is clear that testing counts as contributing, whether or not you&#8217;ve done it before.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Your first contribution to WordPress shouldn’t start with installing Git, Node.js, npm, and Docker. That’s the friction the WordPress Contributor Toolkit removes, and <strong>Ryan Welcher</strong> announced <a href=\"https://make.wordpress.org/core/2026/10/23/wordpress-contributor-toolkit-2-0-a-redesigned-app-in-your-language/\"><strong>Contributor Toolkit 2.0, a redesigned app in your language</strong></a>. It’s rebuilt on the WordPress Design System, ships in ten languages, and adds a settings dialog. After you apply a patch, you can revert a single file without losing the patch itself. It’s also about 350 MB smaller, which helps when a whole Contributor Day room downloads it at once.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Jorge Costa</strong> shared <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\"><strong>what&#8217;s new in Gutenberg 24.2</strong></a>, and the Notes feature is the big headline. Notes now float in a margin the editor reserves next to the canvas, so you no longer have to choose between reading feedback and keeping the Settings sidebar open. </p>\n\n\n\n<figure class=\"wp-block-image size-full has-custom-border\"><img alt=\"Screenshot of the WordPress post editor with notes shown in the margin to the right.\" class=\"has-border-color has-steel-500-border-color wp-image-47316\" height=\"1469\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/10/gutenberg-notes-cropped.webp?resize=2048%2C1469&#038;ssl=1\" style=\"border-width: 1px;\" width=\"2048\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The Navigation block&#8217;s link search now looks through pages, posts, categories, and tags at once. Gallery can sort hand-picked images and tint all of them with a single duotone. And the design tools push continues with about 80 more PRs. Minimum width and height controls, for example, went from five blocks to 40. </p>\n\n\n\n<p class=\"wp-block-paragraph\">For developers, React 19 is now on by default. Test your plugins and themes, and if something breaks, you can switch it off under <strong>Gutenberg → Experiments</strong>. Gutenberg 24.3 RC1 is already out, too, with rich text formatting across blocks, so expect that next week.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the Developer Blog, I put together <a href=\"https://developer.wordpress.org/news/2026/10/whats-new-for-developers-october-2026/\"><strong>What&#8217;s new for developers? (October 2026)</strong></a>, and I tried something different this month. Instead of walking through every aspect of the project, it focuses on the changes I think matter most if you build on WordPress: custom blocks building their own responsive controls, <code>wp_kses()</code> being rebuilt on the HTML API, stroke-based Core icons, and the automated security review for plugin releases. Everything else is linked at the end.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Readers may remember <strong>Chris Zarate&#8217;s</strong> post on moving collaboration to the server from the last edition. <strong>Alec Geatches</strong> follows it up with <a href=\"https://make.wordpress.org/core/2026/10/14/real-time-collaboration-a-guide-to-sync-engines/\"><strong>a guide to the sync engines for real-time collaboration</strong></a>, comparing yjs-server, DE-RTC, and intent-log on their strengths and weaknesses. In every engine, each change goes through WordPress, which confirms who sent it, checks their permissions, and validates it before merging. You can try all three in the experimental <a href=\"https://github.com/WordPress/gutenberg-sync-engines\">Gutenberg Sync Engines</a> plugin. It needs WordPress 7.0+ and the <a href=\"https://wordpress.org/plugins/presence-api/\">Presence API plugin</a>, and it bundles its own copy of Gutenberg, so deactivate the Gutenberg plugin first.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Feature Notifications has been quiet since version 0.2.0 shipped in April 2023. <strong>Jonathan Bossenger</strong> is reviving it with a <a href=\"https://make.wordpress.org/core/2026/10/10/feature-notifications-status-update-and-plan-for-0-3-0/\"><strong>status update and plan for 0.3.0</strong></a>, aiming to ship it with WordPress. That would be the project&#8217;s first working MVP: a notifications system that creates, stores, displays, and dismisses notifications. His honest assessment is that the foundations are solid but nothing is wired up end to end yet. He&#8217;s posting <a href=\"https://make.wordpress.org/core/2026/10/23/wp-feature-notifications-weekly-update-2026-10-23/\"><strong>weekly updates</strong></a> if you want to follow along or help.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Benjamin Zekavica</strong> published the <a href=\"https://make.wordpress.org/core/2026/10/19/recap-wordpress-7-1-mary-lou-retrospective/\"><strong>recap of the WordPress 7.1 &#8220;Mary Lou&#8221; retrospective</strong></a>, summarizing what contributors would keep, add, and change for future release squads. If you answered the survey, this is where your feedback landed.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Sticky headers are one of those things you end up fixing on nearly every block theme site. <strong>Jamie Marsland</strong> turned his fix into a free plugin, <a href=\"https://www.pootlepress.com/2026/10/jamies-header-effects-free-sticky-header-plugin/\"><strong>Jamie&#8217;s Header Effects</strong></a>.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">The standout is Chameleon mode: as visitors scroll, the header picks up the background color of the section beneath it and flips its text between light and dark to stay readable. There are also frosted-glass, solid, hide-on-scroll, and transparent overlay styles. It finds your header template part on its own, respects prefers-reduced-motion, and lives under <strong>Appearance → Header Effects</strong>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Meta Box&#8217;s custom models no longer have to sit in isolation. A few weeks after moving model creation into the builder, <strong>Lua Nguyen</strong> announced <a href=\"https://metabox.io/custom-model-field/\"><strong>the new Custom Model field</strong></a>, which lets you pick one or more items from a custom model the same way the Post field picks posts. MB Relationships also gains a Model object type, so you can connect models to posts, terms, users, or other models in either direction. Think hotel rooms as a post type with bookings attached from a custom model—no IDs stored by hand.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">On WordPress.com, <strong>Ronnie Burt</strong> covers <a href=\"https://wordpress.com/blog/2026/10/15/wordpress-agent-updates/\"><strong>what&#8217;s new with WordPress Agent</strong></a>: it now designs a custom theme from your answers, hands you off to a simplified AI Editor with Preview and Edit tabs, and can install and manage plugins when you ask. The latest <a href=\"https://wordpress.com/blog/2026/10/16/changelog-premium-themes-newsletters/\"><strong>WordPress.com changelog</strong></a> also opens premium themes to every paid plan, starting with Personal.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.woocommerce.com/2026/10/09/woocommerce-11-2-1-release-notes/\"><strong>WooCommerce 11.2.1</strong></a> fixes two regressions: classic checkout on stores that remove address fields with filters, and postcode validation in the Checkout block for Argentina and a few other countries.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;ve ever had to explain to a client why they should move to a block theme, <strong>Simon Cooke</strong> has done the work for you. His Human Made guide on <a href=\"https://humanmade.com/full-site-editing/wordpress-fse-block-theme-explained/\"><strong>how a WordPress block theme is built, and why it matters for enterprise sites</strong></a> walks through each part of a block theme and who owns it, with a side-by-side comparison to classic themes. He&#8217;s clear that moving is a project, not a theme swap. The point he lands on: when design rules live in the theme, a page built by someone who joined last week follows the same rules as one the designer built.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">What if you could point a tool at any static HTML and CSS site and get an editable block theme back, headers and footers included? That&#8217;s the Static Site Importer, and <strong>Chris Huber</strong> of Automattic talks it through with <strong>Nathan Wrigley</strong> on WP Tavern in <a href=\"https://wptavern.com/podcast/238-chris-huber-on-how-static-site-importer-makes-migrating-any-website-to-wordpress-easier-than-ever/\"><strong>episode #238 on making migration to WordPress easier than ever</strong></a>. You&#8217;ll hear how it crawls a site, maps HTML elements to blocks, and handles trickier features like WooCommerce, plus how it fits into the broader Data Liberation effort.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WooCommerce&#8217;s Purple theme has a new home. <strong>Luigi Teschio</strong> announced that <a href=\"https://developer.woocommerce.com/2026/10/20/purple-monorepo/\"><strong>Purple development moves to the WooCommerce monorepo</strong></a>, as the first theme in its new themes/ directory, so contributions and bug reports go there now. One of the stated reasons is that keeping themes next to the blocks they use makes it easier for contributors, and AI coding tools, to see how templates and patterns use WooCommerce blocks. Nothing changes for existing installs, and Purple still releases on its own schedule. For more background, <strong>Bob Dunn&#8217;s</strong> Do the Woo episode on <a href=\"https://dothewoo.com/2026/10/15/woocommerce-themes-in-2026-woo-goes-purple-commercegurus-talks-performance/\"><strong>WooCommerce themes in 2026</strong></a> covers Purple and theme performance.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-f2a2f9e80ac7fb20 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The new <code>@wordpress/ui</code> package will gradually replace <code>@wordpress/components</code>, so how much of an existing plugin can you move over today? <strong>Ryan Welcher</strong> found out live by <a href=\"https://www.youtube.com/watch?v=3MJUEC4PTa4\"><strong>migrating Advanced Query Loop to @wordpress/ui with the Design System MCP</strong></a>. </p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Once your page registers WebMCP tools, those tool definitions are an API, and the consumer is a language model. <strong>Pascal Birchler</strong> built <a href=\"https://pascalbirchler.com/testing-webmcp-with-playwright/\"><strong>playwright-webmcp for testing WebMCP tool surfaces</strong></a>, with linting, Playwright matchers, agent evals, and a site audit CLI. He lists the failure modes that make this tricky: vague descriptions the model ignores, schemas the browser quietly rejects, and two tools on the same page with nearly identical names.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Extension developers no longer need to duplicate a WooCommerce ability just to expose a few extra fields. <strong>Luis Felipe Zaguini</strong> opened a <a href=\"https://developer.woocommerce.com/2026/10/22/extensible-abilities/\"><strong>call for testing extensible abilities for extension fields</strong></a>, an experimental API in WooCommerce 11.3. Extensions can add fields to product, order, and order item reads and writes, register query filters, and refuse a change with a validator before it saves. It&#8217;s off by default, so turn on <strong>Extensible abilities</strong> under <strong>WooCommerce → Settings → Advanced → Features</strong> to try it. The gift wrap example in the post is a good place to start.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\"><strong>What&#8217;s new in Playground?</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">The best way to find out what&#8217;s hard about site editing is to watch someone try it. <strong>Jamie Marsland</strong> built <a href=\"https://www.pootlepress.com/2026/10/new-wordpress-user-testing-app-playground-spacefast/\"><strong>a user testing app</strong></a> <strong>for</strong> <a href=\"https://playground-usertest.view.fast/\"><strong>WordPress on Playground and Spacefast</strong></a> to do exactly that. You send a tester a link, and Playground spins up a fresh site in their browser from your existing demo blueprint, with a card of five to seven tasks in the corner. The results page shows how long each task took, who needed the hint, and whether the site actually changed. It&#8217;s also an MCP server, and it&#8217;ll flag a task that gives away the button name.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\"><strong>AI in WordPress</strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Two weeks after the MCP Adapter arrived on WordPress.org as a canonical plugin, the AI team got approval to make MCP a default part of WordPress. <strong>Rae Morey</strong> reports on <a href=\"https://www.therepository.email/wordpress-ai-team-moves-to-make-mcp-a-default-part-of-wordpress-with-7-3-floated-as-a-target\"><strong>the move to make MCP a default part of WordPress, with 7.3 floated as a target</strong></a>. That doesn&#8217;t necessarily mean merging the adapter into Core: bundling it, enabling it through existing interfaces, and building specific capabilities into Core are all on the table. It&#8217;s also a reversal of the reasoning behind the canonical plugin, and maintainers are asking what changed. The <a href=\"https://make.wordpress.org/ai/2026/10/22/ai-contributor-weekly-summary-21-october-2026/\"><strong>AI contributor summary for October 21</strong></a> has the meeting&#8217;s side of the discussion.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Andy Peatling</strong> launched <a href=\"https://wpab.view.fast/\"><strong>WordPress Agent Benchmarks</strong></a> to measure how AI agents handle WordPress, and <strong>Rae Morey</strong> walks through <a href=\"https://www.therepository.email/new-benchmarks-find-ai-agents-overlook-wordpress-and-cant-complete-tasks-via-the-official-mcp-adapter\"><strong>the first results</strong></a>. Across 193 sites built for requests that suited WordPress, agents chose it zero times, even though they named it as an option about half the time. Using the MCP Adapter alone, they completed no tasks on existing sites, largely because it doesn&#8217;t yet bundle the abilities for common operations. <strong>Brian Coords</strong> asks what WordPress would have to change in <a href=\"https://www.briancoords.com/helping-agents-choose-wordpress-w-the-wp-minute/\"><strong>helping agents choose WordPress</strong></a>, drawing on a WP Minute panel with Andy.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Is the MCP Adapter safe? <strong>Brad Williams</strong> of WebDevStudios calls it a door: &#8220;You decide which rooms it opens into.&#8221; He explains why <a href=\"https://webdevstudios.com/2026/10/15/wordpress-mcp-adapter-production/\"><strong>production use of the MCP Adapter is a governance decision</strong></a>, not a plugin decision. An agent gets whatever abilities are exposed, using the permissions of the user it connects as, and every plugin you install can add more. His advice is to write the agent&#8217;s job description before you hand over the keys.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">If you connect an AI client to WooCommerce, this one needs action before you upgrade. <strong>Darren Ethier</strong> explains that <a href=\"https://developer.woocommerce.com/2026/10/21/woocommerce-11-3-mcp/\"><strong>WooCommerce 11.3 removes its deprecated MCP endpoint</strong></a>. Requests to /wp-json/woocommerce/mcp will return a 410. Install the MCP Adapter, create an application password for a user with only the capabilities the client needs, and point the client at the adapter&#8217;s default server. Extensions that hooked into the old endpoint&#8217;s filters should check the post&#8217;s full list of what&#8217;s been removed.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">WPShout&#8217;s guide on <a href=\"https://wpshout.com/connect-claude-to-wordpress/\"><strong>how to connect Claude to WordPress</strong></a> opens with the question most guides skip: where your site is hosted decides which route you take. WordPress.com, Jetpack, and other self-hosted sites each get their own path, and the walkthrough uses a free MCP plugin with a least-privilege grant. It&#8217;s also candid about a gap: the WordPress MCP Adapter has no OAuth server of its own, so claude.ai&#8217;s sign-in can&#8217;t connect to it directly yet.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"wp-block-paragraph\">Post revisions spent years bloating databases. Human Made thinks they&#8217;re about to become valuable. In <a href=\"https://humanmade.com/word-on-the-future/agentic-wordpress-revisions-process-mining/\"><strong>WordPress revisions: agentic gold?</strong></a>, <strong>Noel</strong> argues that every revision records what changed, who changed it, and when, which makes them a log of how your team really works. Mine them for repeated changes and you&#8217;ve found the workflows an agent could take over. The post includes a prompt you can run, on a copy of your database and never on production.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"ng-block-c510e4897880f0a7 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></td>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\">\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p>\n</td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></td>\n</tr>\n</tbody>\n</table>\n<table cellpadding=\"0\" cellspacing=\"0\" class=\"wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\">\n<tbody>\n<tr>\n<td align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\">\n<p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p>\n</td>\n</tr>\n</tbody>\n</table>\n</td>\n<td class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></td>\n</tr>\n<tr>\n<td class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></td>\n</tr>\n</tbody>\n</table>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--1\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-c546b410a6d9b4ca wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide is-style-wide--2\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 24 Oct 2026 16:18:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Justin Tadlock\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: Navigating the Value of Friction in a Fast-Paced World\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564568\";